package ai.moying.iview.plan
import java.time.*
import kotlin.test.*
class ProductionPlanTest{@Test fun `cross midnight shift subtracts device downtime`(){val r=Mem();r.s+=Shift(1,"夜班",20*60,8*60,setOf(DayOfWeek.MONDAY),"UTC",true,1);r.d+=PlannedDowntime(1,7,Instant.parse("2026-01-06T00:00:00Z"),Instant.parse("2026-01-06T01:00:00Z"),"保养",1);val d=ProductionPlanService(r).plannedDuration(7,Instant.parse("2026-01-05T20:00:00Z"),Instant.parse("2026-01-06T08:00:00Z"));assertEquals(Duration.ofHours(11),d)}@Test fun `downtime listing can include all devices or one device plus global entries`(){val r=Mem();r.d+=PlannedDowntime(1,null,Instant.EPOCH,Instant.MAX,"全局",1);r.d+=PlannedDowntime(2,7,Instant.EPOCH,Instant.MAX,"设备",1);r.d+=PlannedDowntime(3,8,Instant.EPOCH,Instant.MAX,"其他",1);val s=ProductionPlanService(r);assertEquals(setOf(1L,2L,3L),s.listDowntime(Instant.EPOCH,Instant.MAX).map{it.id}.toSet());assertEquals(setOf(1L,2L),s.listDowntime(Instant.EPOCH,Instant.MAX,7).map{it.id}.toSet())}}
private class Mem:ProductionPlanRepository{val s=mutableListOf<Shift>();val d=mutableListOf<PlannedDowntime>();override fun shifts()=s;override fun shift(id:Long)=s.find{it.id==id};override fun createShift(c:ShiftCommand)=throw UnsupportedOperationException();override fun updateShift(id:Long,c:ShiftCommand)=null;override fun deleteShift(id:Long)=false;override fun downtime(deviceId:Long,start:Instant,end:Instant)=d.filter{it.deviceId==null||it.deviceId==deviceId};override fun listDowntime(start:Instant,end:Instant,deviceId:Long?)=d.filter{deviceId==null||it.deviceId==null||it.deviceId==deviceId};override fun createDowntime(c:PlannedDowntimeCommand)=throw UnsupportedOperationException();override fun deleteDowntime(id:Long)=false}
